def solve_correct_fixed(input_2s, height=14, width=17):
    output = [[0]*width for _ in range(height)]

    # Step 1: Place original 2s and shadow 2s for even rows
    occ = set()  # Occupied cells (2s)
    for r, c in input_2s:
        output[r][c] = 2
        occ.add((r, c))
        if r % 2 == 0 and c + 8 < width:
            output[r][c+8] = 2
            occ.add((r, c+8))

    # Step 2: Fill horizontal 3s in row 6 (between shadow 2s)
    row6_cols = sorted([c for c in range(width) if output[6][c] == 2])
    for i in range(len(row6_cols) - 1):
        c1, c2 = row6_cols[i], row6_cols[i+1]
        for c in range(c1 + 1, c2):
            output[6][c] = 3

    # Step 3: Fill vertical 3s in each column
    # For each 2 not in row 6, fill toward row 6, STOPPING at the next 2
    for c in range(width):
        cols_2s = sorted([r for r in range(height) if output[r][c] == 2])

        for r0 in cols_2s:
            if r0 == 6:
                continue  # Skip shadows in row 6 itself

            if r0 < 6:
                # Fill downward from r0 to row 6
                # Find the next 2 at or above row 6
                for r in range(r0 + 1, 6):
                    if (r, c) in occ:
                        break  # Stop if there's another 2
                    output[r][c] = 3
            else:
                # r0 > 6, fill upward from r0 to row 6
                # Find the next 2 at or below row 6
                for r in range(r0 - 1, 5, -1):
                    if (r, c) in occ:
                        break  # Stop if there's another 2
                    output[r][c] = 3

    return output

